from pathlib import Path
from PIL import Image
import json,hashlib
P=Path(__file__).resolve().parent;R=P.parents[1];M=R/'character/veld-idle-north-original-master-v1'
for source,name in [(M/'original-idle-master.png','original-idle-master.png'),(M/'clean-idle-master.png','prepared-idle-master.png')]:
 (P/name).write_bytes(source.read_bytes())
master=Image.open(P/'prepared-idle-master.png').convert('RGBA');assert master.size==(256,256)
large=master.resize((768,768),Image.Resampling.NEAREST);plate=Image.new('RGB',(768,768),(12,18,24));plate.paste(large,(0,0),large);plate.save(P/'master-input.png')
prompt='''Locked camera. One rear-view woman facing North, exactly as supplied. Animate one quiet scientific scanner interaction. Hold the supplied standing pose for the first second. Draw a small handheld scanner from her right hip belt, smoothly bend both elbows forward and operate it in front of her chest for a moment, then stow it at the belt and return both arms to the supplied relaxed standing pose. Hold that exact pose for the final second. From this rear view, the hands and scanner are mostly hidden by her torso; the elbows move naturally beside her body. Keep both boots planted in their original places and preserve her rear-facing head, small brown bun, shoulders, back, waist, legs and stance. Preserve the original graphite quilted suit, rear panels and silver fasteners, belt pouches, blue arm patches, metallic knee and boot details, matte finish, original body size and proportions. Flat unchanged lighting and the same dark background. No head turn, stepping, camera motion, glow or suit brightness change. Perform only one draw, inspect and stow action.'''
(P/'prompt.txt').write_text(prompt+'\n',encoding='utf-8')
paths=[M/'original-idle-master.png',M/'clean-idle-master.png',M/'master-reference.json',M/'clean-master-reference.json',M/'raw-clean-master-v1.png',P/'original-idle-master.png',P/'prepared-idle-master.png',P/'master-input.png',P/'prompt.txt',Path(__file__)]
record=dict(reference='character/veld-idle-north-original-master-v1/original-idle-master.png',videoAppearanceInput='prepared-idle-master.png',preparation='Existing built-in whole-source North background/edge cleanup. Not pixel-identical to the original; retain untouched original comparison. No new body artwork, RGB, geometry or local edits during preparation.',inputScale=3,offset=[0,0],background=[12,18,24],standingRuler=148,originalFloor=224,firstAndLastImage='master-input.png',bindings={p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},scope='Full North scanner source trial; not adopted animation. Check original/master/prepared/control, all interior motion and current idle joins before admission.')
(P/'INPUTS.json').write_text(json.dumps(record,indent=2)+'\n');print('Original/prepared North references and identical first/last input prepared')
